// Built-in diagram icons (the ArchFlow set generated by
// scripts/icons/build-icons.mjs) and helpers to use them in the app.
import { ARCHFLOW_ICONS, ARCHFLOW_ICON_CATEGORIES } from './archflowIcons';
import { ICON_NAME_TRANSLATIONS } from './iconNames';

interface AppIcon {
  id: string;
  name: string;
  url: string;
  collection?: string;
  isIsometric?: boolean;
  [key: string]: unknown;
}

export const ARCHFLOW_COLLECTION_IDS = new Set(
  ARCHFLOW_ICON_CATEGORIES.map((c) => {
    return c.id;
  })
);

// Collection of the original isoflow pack the set replaces
const LEGACY_COLLECTION = 'isoflow';

const isPolish = (lang?: string) => {
  return (lang ?? '').toLowerCase().startsWith('pl');
};

// Names for the other languages, matched by the full code (de-DE) or the
// language part alone (de); English when there is none
const translationsFor = (lang?: string) => {
  const code = lang ?? '';
  return (
    ICON_NAME_TRANSLATIONS[code] ??
    Object.entries(ICON_NAME_TRANSLATIONS).find(([key]) => {
      return key.split('-')[0] === code.split('-')[0].toLowerCase();
    })?.[1]
  );
};

const defsById = new Map(
  ARCHFLOW_ICONS.map((def) => {
    return [def.id, def];
  })
);

const iconName = (def: (typeof ARCHFLOW_ICONS)[number], lang?: string) => {
  if (isPolish(lang)) return def.names.pl;
  return translationsFor(lang)?.icons[def.id] ?? def.names.en;
};

export const getArchflowIcons = (lang?: string): AppIcon[] => {
  return ARCHFLOW_ICONS.map((def) => {
    return {
      id: def.id,
      name: iconName(def, lang),
      url: def.url,
      collection: def.collection,
      isIsometric: true
    };
  });
};

// Icon names follow the UI language (the drawings stay the same)
export const localizeIcons = <T extends AppIcon>(icons: T[], lang?: string): T[] => {
  return icons.map((icon) => {
    const def = defsById.get(icon.id);
    if (!def || !ARCHFLOW_COLLECTION_IDS.has(icon.collection ?? '')) return icon;
    const name = iconName(def, lang);
    return icon.name === name ? icon : { ...icon, name };
  });
};

// Icon list for a diagram that was saved with its own copy of the icons:
// built-in icons (old isoflow pack or an older ArchFlow set) are replaced by
// the current ones - same ids, so nodes keep working and get the new
// drawings - while imported icons and icon-pack icons are kept.
export const withCurrentBuiltInIcons = <T extends AppIcon>(
  fileIcons: T[],
  currentIcons: T[]
): T[] => {
  const currentIds = new Set(
    currentIcons.map((icon) => {
      return icon.id;
    })
  );
  return [
    ...currentIcons,
    ...fileIcons.filter((icon) => {
      const collection = icon.collection ?? '';
      return (
        collection !== LEGACY_COLLECTION &&
        !ARCHFLOW_COLLECTION_IDS.has(collection) &&
        !currentIds.has(icon.id)
      );
    })
  ];
};

// Category headings for the icon picker
export const getIconCategoryLabels = (lang?: string): Record<string, string> => {
  const translated = translationsFor(lang)?.categories;
  return Object.fromEntries(
    ARCHFLOW_ICON_CATEGORIES.map((c) => {
      return [c.id, isPolish(lang) ? c.pl : (translated?.[c.id] ?? c.en)];
    })
  );
};
